package dev.barakah.app.data

data class AllahName(
    val id: Int,
    val arabic: String,
    val transliteration: String,
    val englishMeaning: String,
    val arabicMeaning: String,
    val englishMeaningDetail: String = ""
)

object AllahNamesData {
    val names = listOf(
        AllahName(1, "الرَّحْمَن", "Ar-Rahman", "The Beneficent / All-Merciful", "الذي وسعت رحمته كل شيء، البالغ في الرحمة غايتها", "The One who wills goodness and mercy for all His creatures, encompassing everything with His infinite grace."),
        AllahName(2, "الرَّحِيم", "Ar-Rahim", "The Merciful / Ever-Merciful", "المنعم بجلائل النعم ودقائقها، مفيض الرحمة على عباده المطيعين", "The Displayer of specific mercy, particularly to the believers, bestowing both great and subtle blessings."),
        AllahName(3, "الْمَلِك", "Al-Malik", "The King / Sovereign", "صاحب السلطان والقدرة والملك المطلق، المتصرف في الأكوان بأمره", "The Absolute Ruler with total authority and sovereignty over the entire universe and beyond."),
        AllahName(4, "الْقُدُّوس", "Al-Quddus", "The Pure / Sacred", "الطاهر المنزه عن كل نقص وعيب ونظير وشبيه", "The Holy and Pure One, who is absolutely free from any defect, flaw, or similarity to His creation."),
        AllahName(5, "السَّلَام", "As-Salam", "The Source of Peace", "ناشر السلام ومصدر الطمأنينة، السالم من النقص والعيوب", "The Giver of Peace and security, the One whose nature is free from any imperfection or harm."),
        AllahName(6, "الْمُؤْمِن", "Al-Mu'min", "The Giver of Faith", "الذي يصدق عباده بما وعدهم، والمؤمن لعباده مما يخافونه من عذابه", "The One who grants faith and security, performing what He promised and protecting His servants."),
        AllahName(7, "الْمُهَيْمِن", "Al-Muhaymin", "The Guardian / Overseer", "الرقيب الحافظ الشاهد على خلقه بأعمالهم، القائم بأرزاقهم وقضاياهم", "The Protector and Overseer who witnesses all things, maintaining and preserving the entire creation."),
        AllahName(8, "الْعَزِيز", "Al-Aziz", "The Almighty / Honorable", "القوي الممتنع الغالب الذي لا يغلبه شيء، ذو العزة الباهرة", "The Powerful and Invincible One whom no one can overcome, possessing ultimate honor and might."),
        AllahName(9, "الْجَبَّار", "Al-Jabbar", "The Compeller / Restorer", "الذي يجبر كسر القلوب ويداوي الضعفاء، والمنفذ أمره في خلقه عسراً ويسراً", "The Restorer of the broken, the One who heals hearts and whose will prevails over all of creation."),
        AllahName(10, "الْمُتَكَبِّر", "Al-Mutakabbir", "The Supreme / Majestic", "المنفرد بصفات العظمة والكبرياء، الكبير المتعالي عن السوء", "The Supremely Great One who is exclusive in His grandeur, far beyond all earthly attributes."),
        AllahName(11, "الْخَالِق", "Al-Khaliq", "The Creator", "الموجد للأشياء من العدم على غير مثال سابق، المقدر للأقدار", "The One who brings things from non-existence into being, determining their measures and fates."),
        AllahName(12, "الْبَارِئ", "Al-Bari'", "The Maker / Evolver", "الذي خلق الخلق بريئاً من التفاوت والاختلاف، الموجد بمقتضى الحكمة", "The Maker who initiates the creation without any prior model, manifesting each thing with perfection."),
        AllahName(13, "الْمُصَوِّر", "Al-Musawwir", "The Fashioner / Shaper", "الذي يعطي لكل مخلوق صورته المتميزة وشكله وهيئته الخاصة", "The One who designs and shapes each creation according to its unique identity and form."),
        AllahName(14, "الْغَفَّار", "Al-Ghaffar", "The All-Forgiving", "الذي يكثر الغفران لذنوب عباده ويرخي عليها ستره في الدنيا والآخرة", "The One who forgives repeatedly, concealing the faults of His servants in this world and the next."),
        AllahName(15, "الْقَهَّار", "Al-Qahhar", "The Subduer / Dominator", "الغالب الذي يذل له كل شيء، المتفرد بـالقهر والسلطان فوق عباده", "The Irresistible Subduer to whom all creation submits, possessing absolute dominance."),
        AllahName(16, "الْوَهَّاب", "Al-Wahhab", "The Supreme Bestower", "المنعم بغير حساب، المعطي بلا غرض ولا طلب عوض", "The Giver of all things without any expectation of return, bestowing blessings limitlessly."),
        AllahName(17, "الرَّزَّاق", "Ar-Razzaq", "The Provider", "الخالق للأرزاق والمتكفل بإيصالها إلى خلقه وقسمتها بينهم", "The Sustainer who creates and guarantees the provision for all living beings, distributing it wisely."),
        AllahName(18, "الْفَتَّاح", "Al-Fattah", "The Opener / Judge", "الذي يفتح أبواب الرحمة والرزق والخير، ويفصل بين الحق والباطل", "The One who opens the doors of mercy and success, judging between truth and falsehood."),
        AllahName(19, "الْعَلِيم", "Al-Alim", "The All-Knowing", "المحيط علمه بكل شيء، السر والعلانية، الكليات والجزئيات", "The All-Knowing One, whose knowledge encompasses everything, whether hidden or manifest."),
        AllahName(20, "الْقَابِض", "Al-Qabid", "The Withholder / Restrainer", "الذي يقبض الأرزاق بـعدله وحكمته، ويقبض الأرواح عند الموت", "The One who constricts and withholds provision or lives according to His divine justice and wisdom."),
        AllahName(21, "الْبَاسِط", "Al-Basit", "The Expander / Extender", "الذي يوسع الرزق ويقسط بالرحمة والفضل لعباده", "The One who expands and amplifies provision, extending His generosity and mercy to His creation."),
        AllahName(22, "الْخَافِض", "Al-Khafid", "The Abaser", "الذي يخفض الكفار والأشرار بـعقابه، ويخسف بالمستكبرين", "The One who lowers the arrogant and the unjust, humbling them through His divine decree."),
        AllahName(23, "الرَّافِع", "Ar-Rafi'", "The Exalter", "الذي يرفع شأن المقربين والأولياء بالإيمان والطاعة وبسط الفضل", "The Exalter who raises the ranks of the righteous, elevating their status in both worlds."),
        AllahName(24, "الْمُعِزّ", "Al-Mu'izz", "The Bestower of Honor", "الذي يهب العزة لمن يشاء من طاعته وعبادته الصالحة", "The Giver of true honor and dignity to those who obey and follow His guidance."),
        AllahName(25, "الْمُذِلّ", "Al-Mudhill", "The Giver of Dishonor", "الذي يذل العصاة والمستكبرين بخذلانهم وعذابهم الأليم", "The One who humbles and abases those who are arrogant and persistent in their disobedience."),
        AllahName(26, "السَّمِيع", "As-Sami'", "The All-Hearing", "الذي يسمع كل الأصوات والهمسات والسرائر بلا حدود وأدوات", "The One who hears all sounds, whether spoken or whispered in the depth of hearts."),
        AllahName(27, "الْبَصِير", "Al-Basir", "The All-Seeing", "الذي يبصر دقيق الكائنات وخفاياها، ويرى باطن الأمور وظاهرها", "The All-Seeing One who observes everything, from the vastest galaxies to the smallest hidden particles."),
        AllahName(28, "الْحَكَم", "Al-Hakam", "The Impartial Judge", "الحاكم الذي لا يرد قضاؤه، العادل الذي لا يظلم مثقال ذرة", "The Supreme Judge whose decree is final, judging with perfect justice and equity."),
        AllahName(29, "الْعَدْل", "Al-Adl", "The Utterly Just", "المنزه عن الظلم والجور، الواضع لكل شيء موضعه اللائق به", "The Just One who is free from any bias, placing everything in its rightful and correct position."),
        AllahName(30, "اللَّطِيف", "Al-Latif", "The Subtle One", "البر بعباده المحسن إليهم برفق وخفاء، المحيط بدقائق الأمور", "The Subtle and Kind One who acts with gentleness and whose knowledge reaches the most hidden depths."),
        AllahName(31, "الْخَبِير", "Al-Khabir", "The All-Aware", "العالم ببواطن الأشياء وخفايا الصدور وحقائق الأكوان وما وراءها", "The All-Aware, who knows the reality of all things and the secrets hidden within every creation."),
        AllahName(32, "الْحَلِيم", "Al-Halim", "The Forbearing", "الذي يمهل المذنبين ولا يعجل بالعقوبة لعله يتوبون ويرجعون", "The Most Forbearing One who is patient with sinners, allowing them time to repent and return to Him."),
        AllahName(33, "الْعَظِيم", "Al-Azim", "The Magnificent", "المستحق لصفات الكبرياء والجلال، البالغ أقصى مراتب العظمة", "The Magnificent One whose greatness is beyond human imagination and comprehension."),
        AllahName(34, "الْغَفُور", "Al-Ghafur", "The Exceedingly Forgiving", "الذي يمحو الذنوب الكبار بالكلية، المتجاوز عن سيئات التائبين", "The Exceedingly Forgiving One who pardons major sins and repeatedly overlooks faults."),
        AllahName(35, "الشَّكُور", "Ash-Shakur", "The Grateful", "الذي يثيب بـجزيل الأجر على قليل الطاعة والإحسان والصبر", "The Grateful One who rewards a small amount of sincere effort with immense and lasting grace."),
        AllahName(36, "الْعَلِيّ", "Al-Aliy", "The Most High", "المتعالي في ذاته وصفاته عن الأشباه والأنداد والعيوب", "The Most High, who is far above any partner, likeness, or imperfection in His divine essence."),
        AllahName(37, "الْكَبِير", "Al-Kabir", "The Greatest", "العظيم ذو الجلال والشأن المطلق، أكبر من كل كبير ووصف", "The Greatest, who is superior to all in status, status and majesty beyond any description."),
        AllahName(38, "الْحَفِيظ", "Al-Hafiz", "The Preserver", "الحافظ لأعمال خلقه المحيط بها، والحارس للأكوان من الزوال", "The Preserver who protects the heavens and the earth and keeps record of every action of His servants."),
        AllahName(39, "الْمُقِيت", "Al-Muqit", "The Nourisher", "المقيت المقتدر على كل شيء، وخالق الأقوات وموصلها للأبدان والقوافي", "The Sustainer and Provider who creates and delivers nourishment for both the physical and spiritual needs."),
        AllahName(40, "الْحَسِيب", "Al-Hasib", "The Bringer of Judgment", "المحاسب والكافي لعباده المؤمنين المتوكلين عليه", "The Accounter who is sufficient for those who trust Him, and who carefully reckons all deeds."),
        AllahName(41, "الْجَلِيل", "Al-Jalil", "The Majestic", "المتصف بكمال الصفات ونعوت الجلال والنزاهة والعظمة", "The Majestic One, characterized by supreme attributes of grandeur, glory, and divine beauty."),
        AllahName(42, "الْكَرِيم", "Al-Karim", "The Generous", "المتفضل بالجود والإحسان بلا مسألة، واسع البذل والصفح", "The Generous One who bestows countless gifts without being asked, forgiving of His servants' shortcomings."),
        AllahName(43, "الرَّقِيب", "Ar-Raqib", "The Watchful", "الملاحظ لحركات المخلوقات وسكناتها، والمطلع على الصدور", "The All-Watchful One who observes every movement and thought, being never absent from His creation."),
        AllahName(44, "الْمُجِيب", "Al-Mujib", "The Responsive", "الذي يجيب دعاء السائلين وتضرع الداعين بالقبول والإعطاء", "The One who answers the prayers and supplications of those who call upon Him with faith."),
        AllahName(45, "الْوَاسِع", "Al-Wasi'", "The All-Encompassing", "واسع الصفات والرحمة والمغفرة والفضل والقدرة للأكوان", "The All-Encompassing One whose mercy, knowledge, and power extend over all that exists."),
        AllahName(46, "الْحَكِيم", "Al-Hakim", "The All-Wise", "الذي يضع الأمور في مواضعها الصحيحة بعلمه وحكمته المحكمة", "The All-Wise, whose actions are based on perfect knowledge and who places everything in its right place."),
        AllahName(47, "الْوَدُود", "Al-Wadud", "The Loving", "المحب لعباده المؤمنين والمحبوب في قلوبهم باللطف والإحسان", "The Most Loving One who is full of affection for His righteous servants and is loved by them."),
        AllahName(48, "الْمَجِيد", "Al-Majid", "The Glorious", "الشريف الذات، العظيم الأفعال، الواسع الكرم والفضل والملك", "The Glorious and Noble One, possessing ultimate honor and whose deeds are filled with excellence."),
        AllahName(49, "الْبَاعِث", "Al-Ba'ith", "The Resurrector", "الذي يحيي الموتى ويبعث من في القبور للحساب والجزاء", "The One who will bring the dead back to life on the Day of Resurrection for judgment and reward."),
        AllahName(50, "الشَّهِيد", "Ash-Shahid", "The Witness", "المطلع على كل شيء، الحاضر الذي لا يغيب عنه ذرة في وجود", "The witness who is present everywhere and from whom nothing is hidden in the entire existence."),
        AllahName(51, "الْحَقّ", "Al-Haqq", "The Truth", "الموجود ذو الوجود الحقيقي، الثابت بذاته الذي لا يزول ولا يتغير", "The Absolute Truth whose existence is real and unchanging, the only reality upon which everything depends."),
        AllahName(52, "الْوَكِيل", "Al-Wakil", "The Trustee", "المتفرد بـتدبير أمور خلقه الكافي لمن توكل عليه والقيام بمصالحه", "The Ultimate Trustee who handles all affairs perfectly for those who place their full trust in Him."),
        AllahName(53, "الْقَوِيّ", "Al-Qawiy", "The Strong", "الذي له القدرة التامة المطلقة التي لا يعجزها أي قوة أو مقاومة", "The All-Strong whose power is absolute and who cannot be weakened or overcome by anything."),
        AllahName(54, "الْمَتِين", "Al-Matin", "The Firm", "شديد القوة والقدرة، الثابت الذي لا يلحقه وهن ولا تعب", "The Firm and Steadfast One, whose strength is enduring and never subject to fatigue or exhaustion."),
        AllahName(55, "الْوَلِيّ", "Al-Waliy", "The Protecting Friend", "المحب الناصر لأوليائه وعباده الصالحين، المتولي لأمور خلقه", "The Protecting Friend and Ally who supports, loves, and guides His righteous servants."),
        AllahName(56, "الْحَمِيد", "Al-Hamid", "The All-Praiseworthy", "المحمود المحبوب المستحق لعموم الحمد والشكر بذاته وجليل صفاته", "The All-Praiseworthy One who inherently deserves all gratitude and praise for His glorious nature."),
        AllahName(57, "الْمُحْصِي", "Al-Muhsi", "The Accounter", "الذي أحصى كل شيء بعلمه وأعداده وصنوفه، الرقيب المطلع", "The One who reckons and keeps record of every single thing in existence, leaving nothing out."),
        AllahName(58, "الْمُبْدِئ", "Al-Mubdi'", "The Originator", "الذي ابتدأ خلق الأشياء من العدم على غير وجه ولا مثال", "The Originator who started the first creation from nothing, without any previous template."),
        AllahName(59, "الْمُعِيد", "Al-Mu'id", "The Restorer", "الذي يعيد الخلق إلى الحياة مرة أخرى بعد موتهم وهلاكهم", "The Restorer who will recreate all beings after their death, bringing them back to their original state."),
        AllahName(60, "الْمُحْيِي", "Al-Muhyi", "The Giver of Life", "الموجد للحياة في الأبدان والقلوب والأكوان بالروح الفائضة", "The Giver of Life who breathes spirit into bodies and grants spiritual life to the hearts."),
        AllahName(61, "الْمُمِيت", "Al-Mumit", "The Bringer of Death", "الذي يسلب الحياة من الخلايا والأبدان بمشيئته وحكمته", "The Bringer of Death who ordains the end of all living things according to His divine wisdom."),
        AllahName(62, "الْحَيّ", "Al-Hayy", "The Ever-Living", "المتصف بالحياة الدائمة الكاملة التي لا يعتريها فناء ولا زوال", "The Ever-Living One who is undying and whose life is eternal, having neither beginning nor end."),
        AllahName(63, "الْقَيُّوم", "Al-Qayyum", "The Self-Sustaining", "القائم بنفسه والمقيم لغيره، المتكفل بتدبير وحفظ الأكوان", "The Self-Sustaining One who maintains Himself and upon whom the entire creation depends for its existence."),
        AllahName(64, "الْوَاجِد", "Al-Wajid", "The Finder", "الذي يجد كل ما يريده ولا يفوته شيء، الغني عما سواه", "The Finder who finds everything He seeks and for whom nothing is ever lost or out of reach."),
        AllahName(65, "الْمَاجِد", "Al-Majid", "The Magnificent", "العظيم ذو المجد والفضل الواسع المنعم الدائم", "The Magnificent and Noble One, possessing infinite glory and boundless generosity."),
        AllahName(66, "الْوَاحِد", "Al-Wahid", "The Unique / One", "المنفرد بذاته وصفاته وأفعاله، فلا شبيه له ولا شريك", "The Unique One who is indivisible and has no partner in His essence, attributes, or actions."),
        AllahName(67, "الأَحَد", "Al-Ahad", "The Only One", "المتفرد بالأحدية المطلقة، الإله الأحد الصمد الفرد", "The One and Only, the indivisibly Single One who is absolutely unique in His divinity."),
        AllahName(68, "الصَّمَد", "As-Samad", "The Eternal / Absolute", "الذي تصمد وتتجه إليه الخلائق في حاجاتها كلياً لغناه التام وقضاياه", "The Self-Sufficient One upon whom all depend for their needs, while He needs nothing from any."),
        AllahName(69, "الْقَادِر", "Al-Qadir", "The Omnipotent", "المتصف بالقدرة الكاملة لإيجاد الممكنات أو إعدامها بمشيئته", "The Capable and All-Powerful One who has the ability to do anything according to His will."),
        AllahName(70, "الْمُقْتَدِر", "Al-Muqtadir", "The Determiner", "البالغ النهاية في القدرة التي لا يمتنع عليها شيء في الكون", "The All-Determining One whose power is supreme and who executes His decree over all existence."),
        AllahName(71, "الْمُقَدِّم", "Al-Muqaddim", "The Expediter", "الذي يقدم الأشياء ويعطيها مراتبها ويزيحها قبل غيرها بحكمته", "The Expediter who brings forward whatever He wills and grants precedence to whom He chooses."),
        AllahName(72, "الْمُؤَخِّر", "Al-Mu'akhkhir", "The Delayer", "الذي يؤخر ما يشاء من الأشياء والحفاوة والوقائع بعدل وحكمة", "The Delayer who puts back or postpones whatever He wills based on His divine wisdom and justice."),
        AllahName(73, "الأَوَّل", "Al-Awwal", "The First", "المستمر الوجود قبل كل موجود، الذي ليس لوجوده بداية", "The First, whose existence had no beginning and who existed before anything else was created."),
        AllahName(74, "الآخِر", "Al-Akhir", "The Last", "الباقي الوجود بعد فناء المخلوقات، الذي ليس لوجوده نهاية", "The Last, whose existence has no end and who remains after everything else has perished."),
        AllahName(75, "الظَّاهِر", "Az-Zahir", "The Manifest", "الغالب البين بأدلته الباهرة وآياته الساطعة العيانية", "The Manifest One, whose existence is clear and evident through His signs throughout the universe."),
        AllahName(76, "الْبَاطِن", "Al-Batin", "The Hidden", "المحتجب عن إدراك العيون والحواس المطلع على بواطن القلوب", "The Hidden One, who is beyond physical perception but intimately aware of every secret and heart."),
        AllahName(77, "الْوَالِي", "Al-Wali", "The Patron / Governor", "المالك المتصرف بالولاء والنصر لتدبير شؤون المخلوقات", "The Protecting Manager who governs all affairs and oversees the entire creation with authority."),
        AllahName(78, "الْمُتَعَالِي", "Al-Muta'ali", "The Self-Exalted", "المتنزه والسمو عن صفات المخلوقين وتصورات الأفهام", "The Most Exalted, who is far above any limitations or attributes of His creation."),
        AllahName(79, "الْبَرّ", "Al-Barr", "The Source of All Goodness", "المحسن العطوف بعباده، الواسع الفضل والبر والعطاء", "The Source of All Goodness, ever-kind and generous to His servants, providing boundless blessings."),
        AllahName(80, "التَّوَّاب", "At-Tawwab", "The Ever-Relenting", "الذي يقبل توبة التائبين ويرحمهم ويغسل خطاياهم مراراً", "The One who accepts repentance repeatedly from His servants and turns toward them with mercy."),
        AllahName(81, "الْمُنْتَقِم", "Al-Muntaqim", "The Avenger", "الذي يذل العصاة والمجرمين بعقابه الشديد بالعدل والحكمة", "The Just Avenger who punishes the wrongdoers and the persistent sinners according to His justice."),
        AllahName(82, "العَفُوّ", "Al-Afuw", "The Pardoner", "الذي يمحو السيئات ويتجاوز عن معاصي عباده برحمته", "The Pardoner who erases sins and completely removes their traces through His infinite mercy."),
        AllahName(83, "الرَّؤُوف", "Ar-Ra'uf", "The Compassionate", "الرحيم بعباده البليغ في التلطف والرحمة لدفع مشقة وضير", "The Most Gracious and Kind, who has extreme compassion for His servants and eases their burdens."),
        AllahName(84, "مَالِكُ الْمُلْك", "Malik-ul-Mulk", "Owner of All Sovereignty", "المتصرف الملكي المطلق في الأكوان والملكوت بمشيئته", "The Eternal Owner of Sovereignty, the absolute Master of everything in the heavens and the earth."),
        AllahName(85, "ذُو الْجَلَالِ وَالإِكْرَام", "Dhul-Jalali wal-Ikram", "Lord of Majesty and Bounty", "المستحق لأوصاف العظمة والجلال والإكرام لعباده وأوليائه", "The Possessor of Majesty and Honor, who is worthy of all glory and who bestows honors upon His creation."),
        AllahName(86, "الْمُقْسِط", "Al-Muqsit", "The Equitable", "العادل في قسمته، المنصف المظلومين ومقيم العدالة والموازين", "The Equitable One who is just in His distribution and who ensures perfect fairness for all."),
        AllahName(87, "الْجَامِع", "Al-Jami'", "The Gatherer", "الذي يجمع الخلائق يوم الحشر، والجامع لصنوف الكمالات والفضائل", "The Gatherer who will bring all creation together on the Day of Judgment and who unites all virtues."),
        AllahName(88, "الْغَنِيّ", "Al-Ghaniy", "The Rich", "المستغني بذاته وصفاته عن كلي خلقه، المحتاج إليه كل ما سواه", "The Self-Sufficient One who is absolutely independent and whom all creation needs for everything."),
        AllahName(89, "الْمُغْنِي", "Al-Mughni", "The Enricher", "الذي يسد فاقات الخلائق ويغني من يشاء من فضله وكرمه وبسطه", "The Enricher who satisfies the needs of His creatures and grants wealth and success to whom He wills."),
        AllahName(90, "الْمَانِع", "Al-Mani'", "The Withholder / Preventer", "الذي يمنع العسر والبلايا والأعطيات بـحكمته ولطفه", "The Withholder who prevents harm and constrains provision or blessings according to His wisdom."),
        AllahName(91, "الضَّارّ", "Ad-Darr", "The distreesser / Harmer", "المقدر للضرر على من يشاء بمقتضى العقوبة والعدل والحكمة", "The Ordainer of Adversity who brings trials to whom He wills for reasons of justice and testing."),
        AllahName(92, "النَّافِع", "An-Nafi'", "The Propitious / Benefactor", "المقدر للنفع والخير والفضل على من يشاء باللطف والمغفرة", "The Bestower of Benefits who brings good and success to whom He wills through His divine grace."),
        AllahName(93, "النُّور", "An-Nur", "The Light", "الهادي المرشد المنير للسموات والأرض ومجرى النور في النفوس", "The Light who guides and illuminates the heavens and the earth and brings clarity to the souls."),
        AllahName(94, "الْهَادِي", "Al-Hadi", "The Guide", "الذي يهدي القلوب والخلائق إلى سلوك سبيل الرشاد وطاعة الله", "The Guide who shows His creation the path of righteousness and leads the hearts to His truth."),
        AllahName(95, "الْبَدِيع", "Al-Badi'", "The Incomparable Originator", "المبدع للأكوان والجمال على وجه فريد غير ذي شبيه أو مثال سابق", "The Incomparable Originator who created the entire universe without any previous model or likeness."),
        AllahName(96, "الْبَاقِي", "Al-Baqi", "The Everlasting", "الدائم البقاء والوجود الذي لا نهاية له ولا يعتريه سبات فناء", "The Everlasting, whose existence is permanent and which will never end or fade into non-existence."),
        AllahName(97, "الْوَارِث", "Al-Warith", "The Ultimate Inheritor", "الباقي الحي بعد زوال الخلائق والملكوت، والوارث المطلق للكون", "The Ultimate Inheritor who remains after all creation has perished, the final owner of all things."),
        AllahName(98, "الرَّشِيد", "Ar-Rashid", "The Guide to Right Path", "الذي يرشد ويوجه الخلائق بحكمته وتقديره، وعاد الصواب المطلق", "The Absolute Guide who directs all things toward their correct end through His supreme wisdom."),
        AllahName(99, "الصَّبُور", "As-Sabur", "The Extreemly Patient", "الذي لا يعجل بعقوبة العصاة، المتصف بالحلم والصبر الإلهي", "The Patient One who does not hasten to punish the disobedient, granting them respite to turn back.")
    )

}
